CREATE OR REPLACE FUNCTION public.user_can_access_asset(p_organization_id uuid, p_device_id uuid DEFAULT NULL, p_vehicle_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_catalog' AS $$ SELECT public.has_org_role(p_organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER']) OR EXISTS (SELECT 1 FROM public.user_asset_access uaa WHERE uaa.organization_id = p_organization_id AND uaa.user_id = auth.uid() AND (p_device_id IS NULL OR uaa.device_id = p_device_id) AND (p_vehicle_id IS NULL OR uaa.vehicle_id = p_vehicle_id)); $$;